  ["Warlord's Leather"] = { bonuses = {["2"]="+20 Resilience.",["4"]="+20 Agility.",["6"]="For each second you do not attack an enemy you become increasingly Ravenous, making your next melee attack cause bonus damage, increasing with each stack. This effect cannot trigger more than once every 10 seconds."}, members = {["Chest"]=1,["Feet"]=1,["Hands"]=1,["Head"]=1,["Legs"]=1,["Shoulders"]=1}, phase = 4 },
  ["Warlord's Linked"] = { bonuses = {["2"]="+20 Resilience.",["4"]="+20 Agility.",["6"]="Your melee attacks have a chance of restoring 5% base mana. This effect can only occur once every 3 seconds."}, members = {["Chest"]=1,["Feet"]=1,["Hands"]=1,["Head"]=1,["Legs"]=1,["Shoulders"]=1}, phase = 4 },
  ["Warlord's Mail"] = { bonuses = {["2"]="+20 Resilience.",["4"]="Increases spell power by 23.",["6"]="Dealing direct non-critical damage with a spell increases the damage of your next spell critical by 5%, stacks up to 3 times."}, members = {["Chest"]=1,["Feet"]=1,["Hands"]=1,["Head"]=1,["Legs"]=1,["Shoulders"]=1}, phase = 4 },
  ["Warlord's Mooncloth"] = { bonuses = {["2"]="+20 Resilience.",["4"]="Increases spell power by 23.",["6"]="Reduces the duration of the Weakened Soul effect caused by your Power Word: Shield by sec."}, members = {["Chest"]=1,["Feet"]=1,["Hands"]=1,["Head"]=1,["Legs"]=1,["Shoulders"]=1}, phase = 4 },
  ["Warlord's Ornamented"] = { bonuses = {["2"]="+20 Resilience.",["4"]="Increases spell power by 23.",["6"]="Your non-periodic critical heals increase your healing done by your next heal with a cast time by 8%. This effect can only occur once every 3 seconds."}, members = {["Chest"]=1,["Feet"]=1,["Hands"]=1,["Head"]=1,["Legs"]=1,["Shoulders"]=1}, phase = 4 },
  ["Warlord's Plate"] = { bonuses = {["2"]="+20 Resilience.",["4"]="+20 Strength.",["6"]="Your melee abilities have a chance to give you Momentum, increasing your armor penetration by 2% for 12 seconds, stacks up to 10 times. This power slowly wanes, causing you to lose one stack every 4 seconds."}, members = {["Chest"]=1,["Feet"]=1,["Hands"]=1,["Head"]=1,["Legs"]=1,["Shoulders"]=1}, phase = 4 },
  ["Warlord's Ringmail"] = { bonuses = {["2"]="+20 Resilience.",["4"]="Increases spell power by 23.",["6"]="Increases your healing done by 8% to targets below 35% health."}, members = {["Chest"]=1,["Feet"]=1,["Hands"]=1,["Head"]=1,["Legs"]=1,["Shoulders"]=1}, phase = 4 },
  ["Warlord's Satin"] = { bonuses = {["2"]="+20 Resilience.",["4"]="Increases spell power by 23.",["6"]="Dealing periodic spell damage has a chance to deal Shadow damage to your target. If your mana is above 75%, this damage is doubled. If your mana is below 25% the damage is halved, but restores 6% of your base mana."}, members = {["Chest"]=1,["Feet"]=1,["Hands"]=1,["Head"]=1,["Legs"]=1,["Shoulders"]=1}, phase = 4 },
  ["Warlord's Silk"] = { bonuses = {["2"]="+20 Resilience.",["4"]="Increases spell power by 23.",["6"]="Reduces the cast time of your next direct damage spell by 20%. This effect has a 15 seconds cooldown after being consumed."}, members = {["Chest"]=1,["Feet"]=1,["Hands"]=1,["Head"]=1,["Legs"]=1,["Shoulders"]=1}, phase = 4 },
  ["Warlord's Wildhide"] = { bonuses = {["2"]="+20 Resilience.",["4"]="Increases spell power by 23.",["6"]="Your non-periodic damaging spells with a cast time increase your spell haste by 3% for 6 sec, stacks up to 3 times."}, members = {["Chest"]=1,["Feet"]=1,["Hands"]=1,["Head"]=1,["Legs"]=1,["Shoulders"]=1}, phase = 4 },
  ["Wildheart Raiment"] = { bonuses = {["3"]="Directly Healing a target below 50% health makes them take 10% more healing from you until their health returns to max.",["6"]="Increases healing done by 5%. Being affected by any effect that would prevent you from casting spell triggers an absorb shield on your party. This effect has 30 second cooldown and removes the healing done benefit while on cooldown."}, members = {["Chest"]=1,["Feet"]=1,["Hands"]=1,["Head"]=1,["Legs"]=1,["Shoulders"]=1,["Waist"]=1,["Wrists"]=1}, phase = 2 },
